import os
import zipfile


class ZipUtil:

    @staticmethod
    def _zipdir(path, ziph):
        # ziph is zipfile handle
        for root, dirs, files in os.walk(path):
            for f in files:
                ziph.write(os.path.join(root, f), f)

    @staticmethod
    def zipdir(source_dir, target_path):
        index = target_path.rfind('/')
        target_folder = target_path[:index]

        if not os.path.isdir(target_folder):
            os.makedirs(target_folder)

        zipf = zipfile.ZipFile(target_path, 'w', zipfile.ZIP_DEFLATED)
        ZipUtil._zipdir(source_dir, zipf)
        zipf.close()
